// ---------------------------------------------------------------------------
// Selecciona qué clientes dormidos reciben hoy el mensaje de reactivación.
// Corre una vez por ejecución y devuelve un item por mensaje a enviar.
//
// Sirve a dos canales. En EE.UU. el canal es SMS y manda la TCPA: consentimiento
// previo por escrito, horario restringido y opt-out honrado. En México el canal
// es WhatsApp y manda la política de Meta. Las reglas duras de abajo son la
// intersección de ambas, aplicadas siempre.
// ---------------------------------------------------------------------------
const cfg      = $('Config').first().json;
const negocios = $('Leer negocios').all().map(i => i.json);
const clientes = $('Leer clientes').all().map(i => i.json);
const log      = $('Leer log').all().map(i => i.json);
const tarifas  = $('Leer tarifas').all().map(i => i.json);

const ahora = new Date();
const DIA   = 86400000;

const esSi = v => String(v ?? '').trim().toLowerCase() === 'si';
const soloDigitos = t => String(t ?? '').replace(/[^0-9]/g, '');

// --- Reloj local del negocio -----------------------------------------------
// Todo se calcula en la zona horaria de la barbería, no en la del servidor.
// Un cron a las 10:00 UTC son las 4 de la mañana en Texas, y eso es una
// violación de horario, no un detalle.
function enZona(tz, opts, respaldo) {
  try { return new Intl.DateTimeFormat('en-US', { timeZone: tz, ...opts }).format(ahora); }
  catch (e) { return respaldo; }
}
const horaLocal = tz => {
  const h = parseInt(enZona(tz, { hour: '2-digit', hourCycle: 'h23' }, String(ahora.getUTCHours())), 10);
  return Number.isFinite(h) ? h : ahora.getUTCHours();
};
const DOW = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };
const diaLocal = tz => DOW[enZona(tz, { weekday: 'short' }, '')] ?? (((ahora.getUTCDay() + 6) % 7) + 1);
const fechaLocal = tz => {
  const f = enZona(tz, { year: 'numeric', month: '2-digit', day: '2-digit' }, '');
  const m = f.match(/(\d{2})\/(\d{2})\/(\d{4})/);
  return m ? `${m[3]}-${m[1]}-${m[2]}` : ahora.toISOString().slice(0, 10);
};

const diasEntre = (desde, hoy) => {
  const s = String(desde ?? '').trim().slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  const t = Date.parse(s + 'T00:00:00Z');
  if (Number.isNaN(t)) return null;
  return Math.floor((Date.parse(hoy + 'T00:00:00Z') - t) / DIA);
};

const precio = (pais, canal, categoria) => {
  const t = tarifas.find(x =>
    String(x.pais).trim() === String(pais).trim() &&
    String(x.canal).trim() === String(canal).trim() &&
    String(x.categoria).trim() === String(categoria).trim());
  return t ? (Number(t.precio_usd) || 0) : 0;
};

// --- Segmentos SMS ----------------------------------------------------------
// Un SMS no se cobra por mensaje, se cobra por segmento, y el número de
// segmentos depende de la codificación. Si UN solo carácter se sale de GSM-7
// —una tilde, un emoji— el mensaje ENTERO pasa a UCS-2 y la capacidad cae de
// 160 a 70 caracteres. Una "ó" puede triplicar la factura.
const GSM7 = '@£$¥èéùìòÇ\nØø\rÅå'
  + 'Δ_ΦΓΛΩΠΨΣΘΞÆæßÉ'
  + ' !"#¤%&\'()*+,-./0123456789:;<=>?¡'
  + 'ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿'
  + 'abcdefghijklmnopqrstuvwxyzäöñüà';
const GSM7_EXT = '^{}\\[~]|€';

function medirSms(texto) {
  const t = String(texto ?? '');
  let esGsm = true, largo = 0, culpable = '';
  for (const c of t) {
    if (GSM7.indexOf(c) !== -1) largo += 1;
    else if (GSM7_EXT.indexOf(c) !== -1) largo += 2;   // los de extensión ocupan 2
    else { esGsm = false; culpable = c; break; }
  }
  if (!esGsm) {
    // UCS-2 cuenta unidades UTF-16: un emoji fuera del plano básico ocupa 2.
    largo = [...t].reduce((n, c) => n + (c.codePointAt(0) > 0xFFFF ? 2 : 1), 0);
    return { encoding: 'UCS-2', caracteres: largo,
             segmentos: largo <= 70 ? 1 : Math.ceil(largo / 67), culpable };
  }
  return { encoding: 'GSM-7', caracteres: largo,
           segmentos: largo <= 160 ? 1 : Math.ceil(largo / 153), culpable: '' };
}

const rellenar = (plantilla, vals) =>
  String(plantilla ?? '').replace(/\{(\w+)\}/g, (m, k) => (vals[k] ?? m));

// Twilio recibe el cuerpo como formulario, no como JSON.
const formulario = o => Object.entries(o)
  .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');

// --- Último contacto real, reconstruido desde el log ------------------------
const ultimoContacto = {};
for (const l of log) {
  if (String(l.tipo).trim() !== 'reactivacion') continue;
  const k = String(l.cliente_id ?? '').trim();
  const f = String(l.timestamp ?? '').slice(0, 10);
  if (!k || !f) continue;
  if (!ultimoContacto[k] || f > ultimoContacto[k]) ultimoContacto[k] = f;
}

const dryRun = esSi(cfg.modo_prueba) || cfg.modo_prueba === true;
const salida = [];
const descartes = {};
const resumenNegocios = [];

for (const n of negocios) {
  const id = String(n.negocio_id ?? '').trim();
  if (!id) continue;

  const omitir = m => resumenNegocios.push({ negocio_id: id, omitido: m });
  if (!esSi(n.activo)) { omitir('inactivo'); continue; }

  const canal = String(n.canal ?? 'sms').trim().toLowerCase();
  const tz    = String(n.zona_horaria ?? 'America/Chicago').trim();
  const hoy   = fechaLocal(tz);

  // Horario. La TCPA permite 8:00-21:00 hora local del destinatario; aquí se
  // usa 9:00-20:00, más estrecho a propósito: el margen cubre el desfase entre
  // la zona del local y la del cliente, y de paso nadie recibe publicidad
  // mientras cena.
  const hora = horaLocal(tz);
  if (hora < 9 || hora >= 20) { omitir('fuera_de_horario_local_' + hora + 'h'); continue; }

  const habiles = String(n.dias_habiles ?? '').split(',').map(s => s.trim()).filter(Boolean);
  if (habiles.length && !habiles.includes(String(diaLocal(tz)))) { omitir('hoy_no_abre'); continue; }

  if (canal === 'sms' && !String(n.sms_remitente ?? '').trim()) { omitir('sin_remitente_sms'); continue; }
  if (canal === 'whatsapp' && !String(n.phone_number_id ?? '').trim()) { omitir('sin_phone_number_id'); continue; }

  const umbral    = Number(n.umbral_dias)     || 45;
  const umbralMax = Number(n.umbral_max_dias) || 120;
  const cooldown  = Number(n.cooldown_dias)   || 60;
  const tope      = Number(n.max_por_dia)     || 40;

  const marcar = m => { descartes[m] = (descartes[m] || 0) + 1; };
  const candidatos = [];

  for (const c of clientes) {
    if (String(c.negocio_id ?? '').trim() !== id) continue;

    // Consentimiento previo. En EE.UU. no es buena práctica, es la diferencia
    // entre una campaña y una demanda de 500 a 1.500 USD por mensaje.
    if (!esSi(c.consentimiento)) { marcar('sin_consentimiento'); continue; }
    if (esSi(c.optout))          { marcar('optout'); continue; }

    const telefono = soloDigitos(c.telefono);
    if (telefono.length < 10) { marcar('telefono_invalido'); continue; }

    const dormido = diasEntre(c.ultima_visita, hoy);
    if (dormido === null)    { marcar('sin_ultima_visita'); continue; }
    if (dormido < umbral)    { marcar('aun_activo'); continue; }
    if (dormido > umbralMax) { marcar('demasiado_frio'); continue; }

    const prox = diasEntre(c.proxima_cita, hoy);
    if (prox !== null && prox <= 0) { marcar('ya_tiene_cita'); continue; }

    const desdeContacto = diasEntre(ultimoContacto[String(c.cliente_id).trim()] ?? c.ultimo_contacto, hoy);
    if (desdeContacto !== null && desdeContacto < cooldown) { marcar('en_cooldown'); continue; }

    candidatos.push({ cliente: c, telefono, dormido });
  }

  // Primero los que llevan menos tiempo dormidos: son los más recuperables.
  candidatos.sort((a, b) => a.dormido - b.dormido);
  const elegidos = candidatos.slice(0, tope);

  let costoNegocio = 0;
  let segmentosNegocio = 0;

  for (const cand of elegidos) {
    const c = cand.cliente;
    const nombre = (String(c.nombre ?? '').trim().split(/\s+/)[0]) || 'hola';
    const negocioNombre = String(n.nombre_corto || n.nombre || '').trim();
    const servicio = String(c.servicio_habitual || '').trim() || 'tu corte de siempre';

    const comun = {
      negocio_id: id,
      negocio_nombre: negocioNombre,
      canal,
      zona_horaria: tz,
      cliente_id: String(c.cliente_id ?? '').trim(),
      nombre,
      nombre_completo: String(c.nombre ?? '').trim(),
      telefono: cand.telefono,
      servicio,
      dias_dormido: cand.dormido,
      envio_real: !dryRun,
      telefono_dueno: soloDigitos(n.telefono_dueno),
    };

    if (canal === 'sms') {
      const texto = rellenar(n.sms_plantilla, {
        nombre, negocio: negocioNombre, servicio,
        nombre_completo: comun.nombre_completo, telefono: cand.telefono,
      });
      const m = medirSms(texto);
      const unit = precio(n.pais, 'sms', 'segmento');
      const costo = Number((m.segmentos * unit).toFixed(5));
      costoNegocio += costo;
      segmentosNegocio += m.segmentos;

      const remitente = String(n.sms_remitente).trim();
      salida.push({ json: { ...comun,
        categoria: 'segmento',
        plantilla: 'sms_plantilla',
        sms_texto: texto,
        encoding: m.encoding,
        segmentos: m.segmentos,
        caracteres: m.caracteres,
        // Se avisa cuando un carácter suelto disparó el costo.
        aviso_encoding: m.culpable
          ? `"${m.culpable}" saca el mensaje de GSM-7: ${m.segmentos} segmentos en vez de 1`
          : '',
        costo_estimado_usd: costo,
        sms_form: formulario({
          To: '+' + cand.telefono,
          Body: texto,
          ...(remitente.startsWith('MG') ? { MessagingServiceSid: remitente } : { From: remitente }),
        }),
        payload: null,
      }});
    } else {
      const unit = precio(n.pais, 'whatsapp', 'marketing');
      costoNegocio += unit;
      salida.push({ json: { ...comun,
        categoria: 'marketing',
        plantilla: String(n.plantilla_reactivacion || '').trim(),
        encoding: '',
        segmentos: '',
        caracteres: '',
        aviso_encoding: '',
        costo_estimado_usd: unit,
        sms_texto: '',
        sms_form: '',
        phone_number_id: String(n.phone_number_id).trim(),
        payload: {
          messaging_product: 'whatsapp',
          recipient_type: 'individual',
          to: cand.telefono,
          type: 'template',
          template: {
            name: String(n.plantilla_reactivacion || '').trim(),
            language: { code: String(n.idioma_plantilla || 'es_MX').trim() },
            components: [
              { type: 'body', parameters: [
                { type: 'text', text: nombre },
                { type: 'text', text: negocioNombre },
                { type: 'text', text: servicio },
              ]},
              { type: 'button', sub_type: 'quick_reply', index: '0',
                parameters: [{ type: 'payload', payload: 'AGENDAR' }] },
              { type: 'button', sub_type: 'quick_reply', index: '1',
                parameters: [{ type: 'payload', payload: 'AHORA_NO' }] },
              { type: 'button', sub_type: 'quick_reply', index: '2',
                parameters: [{ type: 'payload', payload: 'BAJA' }] },
            ],
          },
        },
      }});
    }
  }

  resumenNegocios.push({
    negocio_id: id,
    canal,
    hora_local: hora,
    candidatos: candidatos.length,
    elegidos: elegidos.length,
    frenados_por_tope: Math.max(0, candidatos.length - elegidos.length),
    segmentos: segmentosNegocio || undefined,
    costo_estimado_usd: Number(costoNegocio.toFixed(4)),
  });
}

// Lo primero que se mira cuando alguien pregunta "¿por qué hoy solo salieron 3?".
console.log('modo_prueba=' + dryRun);
console.log('por_negocio=' + JSON.stringify(resumenNegocios));
console.log('descartes=' + JSON.stringify(descartes));
const avisos = salida.filter(s => s.json.aviso_encoding).map(s => s.json.aviso_encoding);
if (avisos.length) console.log('AVISO_COSTO=' + JSON.stringify([...new Set(avisos)]));

return salida;

// Traduce la respuesta de Twilio a una fila de log. Una vez por item.
const origen = $('Lote de envío').item.json;
const res    = $json;
const cuerpo = res.body ?? res;
const status = Number(res.statusCode ?? 200);

const sid     = cuerpo?.sid ?? '';
const errNodo = res.error ?? null;
// Twilio devuelve el error en el propio cuerpo, con su código numérico.
const codApi  = cuerpo?.code ?? null;

let estado = 'enviado', codigo = '', mensaje = '';
if (errNodo)            { estado = 'error'; codigo = String(errNodo.code ?? 'nodo'); mensaje = String(errNodo.message ?? errNodo); }
else if (codApi)        { estado = 'error'; codigo = String(codApi); mensaje = String(cuerpo.message ?? ''); }
else if (status >= 400) { estado = 'error'; codigo = String(status); mensaje = JSON.stringify(cuerpo); }
else if (!sid)          { estado = 'error'; codigo = 'sin_sid'; mensaje = JSON.stringify(cuerpo); }

// Twilio acepta el mensaje como 'queued'; que llegue se sabe después, por el
// webhook de estado. Un 201 aquí significa aceptado, no entregado.
const CATALOGO = {
  '20003': ['Credenciales de Twilio inválidas.', 'avisar_operador'],
  '20429': ['Demasiadas peticiones a la API de Twilio.', 'reintentar_manana'],
  '21211': ['El número de destino no tiene formato válido E.164.', 'descartar_numero'],
  '21214': ['El número de destino no es alcanzable.', 'descartar_numero'],
  '21408': ['La cuenta no tiene permiso para enviar a esa región.', 'avisar_operador'],
  '21606': ['El remitente no es un número de Twilio con SMS habilitado.', 'avisar_operador'],
  '21610': ['El cliente hizo opt-out en el operador. Márcalo en la hoja.', 'descartar_numero'],
  '21614': ['El número de destino no es móvil: no puede recibir SMS.', 'descartar_numero'],
  '30003': ['Teléfono apagado o fuera de cobertura.', 'reintentar_manana'],
  '30005': ['El número no existe o fue dado de baja.', 'descartar_numero'],
  '30006': ['Es una línea fija o el operador no acepta SMS.', 'descartar_numero'],
  '30007': ['El operador filtró el mensaje como spam. Revisa el texto y el volumen.', 'avisar_operador'],
  '30034': ['El número no está registrado en A2P 10DLC. Los operadores bloquean todo.', 'avisar_operador'],
  '30032': ['Tipo de mensaje no permitido para este remitente.', 'avisar_operador'],
};

let diagnostico = '', accion = 'ninguna';
if (estado === 'error') {
  const hit = CATALOGO[codigo];
  diagnostico = hit ? hit[0] : ('Error no catalogado: ' + mensaje).slice(0, 200);
  accion      = hit ? hit[1] : 'avisar_operador';
}

return { json: {
  timestamp: new Date().toISOString(),
  negocio_id: origen.negocio_id, cliente_id: origen.cliente_id, telefono: origen.telefono,
  canal: 'sms', tipo: 'reactivacion', categoria: origen.categoria, plantilla: origen.plantilla,
  encoding: origen.encoding, segmentos: origen.segmentos,
  wamid: sid, estado, error_code: codigo, error_mensaje: mensaje.slice(0, 300),
  costo_estimado_usd: estado === 'enviado' ? origen.costo_estimado_usd : 0,
  facturable: '', respondio: 'no', agendo: 'no', dias_dormido: origen.dias_dormido,
  diagnostico: diagnostico || origen.aviso_encoding, accion,
}};

// Traduce la respuesta de la WhatsApp Cloud API a una fila de log. Una vez por item.
const origen = $('Lote de envío').item.json;
const res    = $json;
const cuerpo = res.body ?? res;
const status = Number(res.statusCode ?? 200);

const id     = cuerpo?.messages?.[0]?.id ?? '';
const errApi = cuerpo?.error ?? null;
const errNodo = res.error ?? null;

let estado = 'enviado', codigo = '', mensaje = '';
if (errNodo)          { estado = 'error'; codigo = String(errNodo.code ?? 'nodo'); mensaje = String(errNodo.message ?? errNodo); }
else if (errApi)      { estado = 'error'; codigo = String(errApi.code ?? status); mensaje = String(errApi.error_data?.details ?? errApi.message ?? ''); }
else if (status >= 400) { estado = 'error'; codigo = String(status); mensaje = JSON.stringify(cuerpo); }
else if (!id)         { estado = 'error'; codigo = 'sin_wamid'; mensaje = JSON.stringify(cuerpo); }

const CATALOGO = {
  '4':      ['Límite de peticiones de la app alcanzado.', 'reintentar_manana'],
  '80007':  ['Límite de peticiones de la app alcanzado.', 'reintentar_manana'],
  '130429': ['Límite de mensajes por segundo alcanzado.', 'reintentar_manana'],
  '131048': ['Límite de calidad del número: Meta frenó el envío.', 'avisar_operador'],
  '131049': ['Meta no entregó el mensaje por sus límites de marketing por usuario.', 'reintentar_manana'],
  '130472': ['El usuario está en un experimento de Meta y no recibe marketing.', 'reintentar_manana'],
  '131026': ['El número no puede recibir mensajes (probablemente no tiene WhatsApp).', 'descartar_numero'],
  '131047': ['Fuera de la ventana de 24h y el mensaje no era plantilla.', 'avisar_operador'],
  '133010': ['El número del negocio no está registrado en la Cloud API.', 'avisar_operador'],
  '190':    ['El token de acceso caducó o fue revocado.', 'avisar_operador'],
  '132000': ['La plantilla existe pero el número de parámetros no coincide.', 'avisar_operador'],
  '132001': ['La plantilla no existe o no está aprobada en ese idioma.', 'avisar_operador'],
  '132007': ['El formato de la plantilla viola las políticas de WhatsApp.', 'avisar_operador'],
  '132012': ['Un parámetro de la plantilla tiene formato inválido.', 'avisar_operador'],
  '132015': ['La plantilla está pausada por baja calidad.', 'avisar_operador'],
  '132016': ['La plantilla fue deshabilitada definitivamente por calidad.', 'avisar_operador'],
};

let diagnostico = '', accion = 'ninguna';
if (estado === 'error') {
  const hit = CATALOGO[codigo];
  diagnostico = hit ? hit[0] : ('Error no catalogado: ' + mensaje).slice(0, 200);
  accion      = hit ? hit[1] : 'avisar_operador';
}

return { json: {
  timestamp: new Date().toISOString(),
  negocio_id: origen.negocio_id, cliente_id: origen.cliente_id, telefono: origen.telefono,
  canal: 'whatsapp', tipo: 'reactivacion', categoria: origen.categoria, plantilla: origen.plantilla,
  encoding: '', segmentos: '',
  wamid: id, estado, error_code: codigo, error_mensaje: mensaje.slice(0, 300),
  costo_estimado_usd: estado === 'enviado' ? origen.costo_estimado_usd : 0,
  facturable: '', respondio: 'no', agendo: 'no', dias_dormido: origen.dias_dormido,
  diagnostico, accion,
}};

// Modo prueba: misma fila de log que el envío real, sin tocar ninguna API.
// Sirve para validar la selección y el costo con datos reales antes de gastar.
const o = $json;
return { json: {
  timestamp: new Date().toISOString(),
  negocio_id: o.negocio_id, cliente_id: o.cliente_id, telefono: o.telefono,
  canal: o.canal, tipo: 'reactivacion', categoria: o.categoria, plantilla: o.plantilla,
  encoding: o.encoding, segmentos: o.segmentos,
  wamid: '', estado: 'simulado', error_code: '', error_mensaje: '',
  costo_estimado_usd: 0, facturable: '', respondio: 'no', agendo: 'no',
  dias_dormido: o.dias_dormido,
  diagnostico: 'MODO PRUEBA: no se envió. Habría costado ' + o.costo_estimado_usd + ' USD.'
    + (o.aviso_encoding ? ' | ' + o.aviso_encoding : ''),
  accion: 'ninguna',
}};

// Agrupa lo enviado hoy por negocio: una fila de resumen para el operador y,
// si hubo envíos, un aviso al dueño. Ese aviso es lo que evita la cancelación
// a los tres meses: un servicio que no se ve, se cancela.
const filas    = $input.all().map(i => i.json).filter(f => f && f.negocio_id);
const negocios = $('Leer negocios').all().map(i => i.json);

const soloDigitos = t => String(t ?? '').replace(/[^0-9]/g, '');
const rellenar = (p, v) => String(p ?? '').replace(/\{(\w+)\}/g, (m, k) => (v[k] ?? m));
const formulario = o => Object.entries(o)
  .map(([k, x]) => encodeURIComponent(k) + '=' + encodeURIComponent(x)).join('&');

const porNegocio = {};
for (const f of filas) {
  const k = String(f.negocio_id);
  porNegocio[k] ??= { enviados: 0, errores: 0, simulados: 0, segmentos: 0, costo: 0, incidencias: [] };
  const g = porNegocio[k];
  if (f.estado === 'enviado')       g.enviados++;
  else if (f.estado === 'simulado') g.simulados++;
  else {
    g.errores++;
    if (f.accion === 'avisar_operador' && f.diagnostico) g.incidencias.push(f.error_code + ': ' + f.diagnostico);
  }
  g.segmentos += Number(f.segmentos) || 0;
  g.costo += Number(f.costo_estimado_usd) || 0;
}

const salida = [];
for (const [id, g] of Object.entries(porNegocio)) {
  const n = negocios.find(x => String(x.negocio_id).trim() === id) || {};
  const canal = String(n.canal ?? 'sms').trim().toLowerCase();
  const incidencias = [...new Set(g.incidencias)];
  const telDueno = soloDigitos(n.telefono_dueno);
  const negocioCorto = String(n.nombre_corto || n.nombre || '').trim();

  const plantillaOk = canal === 'sms'
    ? !!String(n.sms_resumen || '').trim()
    : !!String(n.plantilla_resumen || '').trim();
  const avisar = g.enviados > 0 && !!telDueno && plantillaOk;

  let smsForm = '', payload = null;
  if (avisar && canal === 'sms') {
    const remitente = String(n.sms_remitente || '').trim();
    smsForm = formulario({
      To: '+' + telDueno,
      Body: rellenar(n.sms_resumen, { negocio: negocioCorto, enviados: String(g.enviados) }),
      ...(remitente.startsWith('MG') ? { MessagingServiceSid: remitente } : { From: remitente }),
    });
  } else if (avisar) {
    payload = {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: telDueno, type: 'template',
      template: {
        name: String(n.plantilla_resumen).trim(),
        language: { code: String(n.idioma_plantilla || 'es_MX').trim() },
        components: [{ type: 'body', parameters: [
          { type: 'text', text: negocioCorto },
          { type: 'text', text: String(g.enviados) },
        ]}],
      },
    };
  }

  salida.push({ json: {
    timestamp: new Date().toISOString(),
    fecha: new Date().toISOString().slice(0, 10),
    negocio_id: id, canal,
    enviados: g.enviados, errores: g.errores, simulados: g.simulados,
    segmentos: g.segmentos,
    costo_estimado_usd: Number(g.costo.toFixed(4)),
    incidencias: incidencias.join(' | '),
    requiere_atencion: incidencias.length ? 'si' : 'no',
    avisar_dueno: avisar,
    es_sms: canal === 'sms',
    phone_number_id: String(n.phone_number_id || '').trim(),
    sms_form: smsForm,
    payload_resumen: payload,
  }});
}

return salida;
